const API='/api';
let state={token:localStorage.getItem('nestledgerToken'),user:JSON.parse(localStorage.getItem('nestledgerUser')||'null'),role:'resident',page:'dashboard'};
const $=s=>document.querySelector(s); const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3000)}
async function api(path,opt={}){opt.headers={...(opt.body?{'Content-Type':'application/json'}:{}),...(opt.headers||{})};if(state.token)opt.headers.Authorization=`Bearer ${state.token}`;const r=await fetch(API+path,opt);let d={};try{d=await r.json()}catch{}if(r.status===401){logout(false)}if(!r.ok)throw new Error(d.error||i18n.t('requestFailed'));return d}
function saveSession(d){state.token=d.token;state.user=d.user;localStorage.setItem('nestledgerToken',d.token);localStorage.setItem('nestledgerUser',JSON.stringify(d.user))}
function logout(show=true){localStorage.removeItem('nestledgerToken');localStorage.removeItem('nestledgerUser');state={token:null,user:null,role:'resident',page:'dashboard'};NLVoice.unmountMicButton&&NLVoice.unmountMicButton();NLChatbot&&NLChatbot.close&&NLChatbot.close();const fab=document.getElementById('chatbotFab');if(fab)fab.remove();const panel=document.getElementById('chatbotPanel');if(panel)panel.remove();render();if(show)toast(i18n.t('loggedOut'))}
function render(){if(!state.token||!state.user)return renderAuth('login');state.role=state.user.role;renderShell()}
function renderAuth(mode='login'){let isLogin=mode==='login';$('#app').innerHTML=`<div class="auth"><section class="auth-art"><div class="brand">${i18n.t('appName')}<span> / community OS</span></div><div class="art-copy"><h1>${i18n.t('heroTitle')}</h1><p>${i18n.t('heroSubtitle')}</p><div class="art-grid"><div class="mini"><b>24/7</b><small>${i18n.t('digitalAccess')}</small></div><div class="mini"><b>₹</b><small>${i18n.t('securePayments')}</small></div></div></div></section><section class="auth-panel">${langSelectHtml()}<div class="auth-card">${isLogin?loginForm():registerForm()}</div></section></div>`;const authCard=$('.auth-card');if(!isLogin&&authCard)authCard.classList.add('register-card');bindAuth(mode)}
function roleButtons(selected){return `<div class="role-switch">${['resident','vendor','admin'].map(r=>`<button type="button" class="role-btn ${selected===r?'active':''}" data-role="${r}">${r==='resident'?'🏠 '+i18n.t('resident'):r==='vendor'?'🛠 '+i18n.t('vendor'):'🛡 '+i18n.t('admin')}</button>`).join('')}</div>`}
function loginForm(){return `<div class="brand" style="color:var(--accent)">${i18n.t('appName')}</div><h2>${i18n.t('welcomeBack')}</h2><p class="sub">${i18n.t('welcomeBackSub')}</p><div id="authError"></div>${roleButtons('resident')}<form id="loginForm"><div class="field"><label>${i18n.t('email')}</label><input id="email" type="email" required placeholder="you@example.com"></div><div class="field"><label>${i18n.t('password')}</label><input id="password" type="password" required placeholder="••••••••"></div><button class="primary">${i18n.t('enterWorkspace')} →</button></form><div class="switch-link"><a id="forgotPassword">Forgot password?</a></div><div class="switch-link">${i18n.t('newHere')} <a id="toRegister">${i18n.t('register')}</a></div>`}
function registerForm(){return `<div class="brand" style="color:var(--accent)">${i18n.t('appName')}</div><h2>${i18n.t('createAccount')}</h2><p class="sub">${i18n.t('joinCommunitySub')}</p><div id="authError"></div><div class="role-switch"><button type="button" class="role-btn active">🏠 ${i18n.t('resident')}</button></div><form id="registerForm" novalidate><div class="field"><label>${i18n.t('name')}</label><input id="name" required placeholder="${i18n.t('name')}"><div class="field-error" id="err-name"></div></div><div class="grid2"><div class="field"><label>${i18n.t('email')}</label><input id="email" type="email" required placeholder="you@example.com"><div class="field-error" id="err-email"></div></div><div class="field"><label>${i18n.t('phone')}</label><input id="phone" placeholder="9876543210"><div class="field-error" id="err-phone"></div></div></div><div class="field"><label>${i18n.t('apartment')}</label><input id="apartment" placeholder="A-204"></div><div class="field"><label>${i18n.t('password')}</label><input id="password" type="password" minlength="8" required placeholder="••••••••"><div class="field-error" id="err-password"></div></div><button class="primary">${i18n.t('register')} →</button></form><div class="switch-link">${i18n.t('alreadyRegistered')} <a id="toLogin">${i18n.t('signIn')}</a></div>`}
function fieldError(id,msg){const el=document.getElementById('err-'+id);if(el)el.textContent=msg||''}
function clearFieldErrors(){document.querySelectorAll('.field-error').forEach(el=>el.textContent='')}
function validEmail(v){return /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(v)}
function validPhone(v){return !v || /^[6-9][0-9]{9}$/.test(v.replace(/\D/g,'').slice(-10))}
let selectedRole='resident';
function bindAuth(mode){selectedRole='resident';document.querySelectorAll('.role-btn[data-role]').forEach(b=>b.onclick=()=>{selectedRole=b.dataset.role;document.querySelectorAll('.role-btn[data-role]').forEach(x=>x.classList.toggle('active',x===b));});if($('#toRegister'))$('#toRegister').onclick=()=>renderAuth('register');if($('#toLogin'))$('#toLogin').onclick=()=>renderAuth('login');if($('#forgotPassword'))$('#forgotPassword').onclick=forgotPasswordModal;if(mode==='login')$('#loginForm').onsubmit=doLogin;else $('#registerForm').onsubmit=doRegister;if($('#langSelect'))$('#langSelect').onchange=e=>{i18n.setLanguage(e.target.value);renderAuth(mode)}}
function forgotPasswordModal(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button class="close" onclick="$('#modal').remove()">×</button><h3>Reset resident password</h3><p class="muted">Use the temporary password provided when your resident account was created.</p><form id="forgotForm"><div class="field"><label>Email</label><input id="fpEmail" type="email" required></div><div class="field"><label>Temporary password</label><input id="fpCurrent" type="password" required></div><div class="field"><label>New password</label><input id="fpNew" type="password" minlength="8" required></div><button class="primary">Change password</button></form></div></div>`);$('#forgotForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/auth/forgot-password',{method:'POST',body:JSON.stringify({email:$('#fpEmail').value,current_password:$('#fpCurrent').value,new_password:$('#fpNew').value})});$('#modal').remove();toast(d.message)}catch(x){toast(x.message)}}}
async function doLogin(e){e.preventDefault();const err=$('#authError');err.innerHTML='';try{const d=await api('/auth/login',{method:'POST',body:JSON.stringify({email:$('#email').value,password:$('#password').value,role:selectedRole})});saveSession(d);render();toast(i18n.t('welcomeToApp'));}catch(x){err.innerHTML=`<div class="error">${esc(x.message)}</div>`}}
async function doRegister(e){e.preventDefault();const err=$('#authError');err.innerHTML='';clearFieldErrors();let ok=true;
    if(!$('#name').value.trim()){fieldError('name',i18n.t('requiredField'));ok=false}
    if(!validEmail($('#email').value.trim())){fieldError('email',i18n.t('invalidEmail'));ok=false}
    if(!validPhone($('#phone').value.trim())){fieldError('phone',i18n.t('invalidPhone'));ok=false}
    if($('#password').value.length<8){fieldError('password',i18n.t('weakPassword'));ok=false}
    if(!ok)return;
    try{const d=await api('/auth/register',{method:'POST',body:JSON.stringify({name:$('#name').value,email:$('#email').value,phone:$('#phone').value,apartment:$('#apartment').value,password:$('#password').value,role:'resident'})});toast(d.message);renderAuth('login');}catch(x){err.innerHTML=`<div class="error">${esc(x.message)}</div>`}}
function navItems(){if(state.role==='resident')return [['dashboard','⌂','dashboard'],['payments','₹','payments'],['receipts','▣','receipts'],['workorders','🛠','maintenance'],['complaints','!','complaints'],['notices','◈','notices'],['profile','○','profile']];if(state.role==='vendor')return [['dashboard','⌂','dashboard'],['workorders','✓','workorders'],['profile','○','profile']];return [['dashboard','⌂','dashboard'],['residents','♙','residents'],['payments','₹','payments'],['workorders','🛠','workorders'],['complaints','!','complaints'],['vendors','⚒','vendors'],['vendorperformance','★','vendorPerformance'],['expenses','◫','expenses'],['notices','◈','notices'],['profile','○','profile']]}
function langSelectHtml(){return `<select class="lang-select" id="langSelect">${i18n.LANGUAGES.map(([code,label])=>`<option value="${code}" ${i18n.getLanguage()===code?'selected':''}>${label}</option>`).join('')}</select>`}
async function renderBell(){const box=$('#bellCount');const panel=$('#notifPanel');try{const d=await api('/notifications');if(box)box.innerHTML=d.unread_count?`<span class="bell-dot">${d.unread_count}</span>`:'';if(panel)panel.dataset.items=JSON.stringify(d.notifications)}catch(e){}}
function renderNotifPanel(){const panel=$('#notifPanel');if(!panel)return;const items=JSON.parse(panel.dataset.items||'[]');panel.innerHTML=`<div class="notif-panel-head"><h4>${i18n.t('notifications')}</h4><a id="markAllRead">${i18n.t('markAllRead')}</a></div>${items.length?items.map(n=>`<div class="notif-item ${n.is_read?'':'unread'}" data-id="${n.id}"><b>${esc(n.title)}</b><p>${esc(n.message)}</p></div>`).join(''):`<div class="notif-item"><p>${i18n.t('noNotifications')}</p></div>`}`;panel.querySelectorAll('.notif-item[data-id]').forEach(el=>el.onclick=async()=>{await api(`/notifications/${el.dataset.id}/read`,{method:'PATCH'});await renderBell();renderNotifPanel()});const mar=$('#markAllRead');if(mar)mar.onclick=async()=>{await api('/notifications/read-all',{method:'PATCH'});await renderBell();renderNotifPanel()}}
function renderShell(){const items=navItems();$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="side-brand"><div class="brand">${i18n.t('appName')}</div><small>${i18n.t(state.role)?.toUpperCase()||state.role.toUpperCase()} ${i18n.t('workspaceLabel')}</small>${langSelectHtml()}</div><div class="profile-chip"><div class="avatar">${esc((state.user.name||'U')[0].toUpperCase())}</div><div><b>${esc(state.user.name)}</b><small>${esc(i18n.t(state.role))}</small></div></div><nav class="nav">${items.map(x=>`<button class="${state.page===x[0]?'active':''}" data-page="${x[0]}"><span style="display:inline-block;width:24px">${x[1]}</span>${i18n.t(x[2])}</button>`).join('')}</nav><button class="logout" id="logout">↪ ${i18n.t('logout')}</button></aside><main class="main"><div class="topbar"><div><h1>${state.role==='resident'?i18n.t('goodEvening')+', '+esc(state.user.name.split(' ')[0])+' 👋':state.role==='vendor'?i18n.t('vendorWorkspace'):i18n.t('adminControlRoom')}</h1><p>${i18n.t('everythingInOnePlace')}</p></div><div class="topbar-actions"><div class="bell-wrap"><button class="bell-btn" id="bellBtn">🔔<span id="bellCount"></span></button><div class="notif-panel" id="notifPanel" style="display:none"></div></div></div></div><div id="content"></div></main></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;renderShell()});$('#logout').onclick=()=>logout();$('#langSelect').onchange=e=>{i18n.setLanguage(e.target.value);renderShell();NLVoice.refreshLabel&&NLVoice.refreshLabel();NLChatbot&&NLChatbot.refreshLabel&&NLChatbot.refreshLabel()};$('#bellBtn').onclick=async()=>{const p=$('#notifPanel');const open=p.style.display==='block';p.style.display=open?'none':'block';if(!open){renderNotifPanel()}};document.addEventListener('click',e=>{const p=$('#notifPanel');if(p&&p.style.display==='block'&&!p.contains(e.target)&&e.target.id!=='bellBtn')p.style.display='none'},{once:true});renderBell();NLChatbot&&NLChatbot.mount&&NLChatbot.mount();loadPage()}
async function loadPage(){const c=$('#content');c.innerHTML=`<div class="panel empty">${i18n.t('loading')}</div>`;try{if(state.page==='dashboard')return await dashboard(c);if(state.page==='payments')return await payments(c);if(state.page==='receipts')return await receipts(c);if(state.page==='complaints')return await complaints(c);if(state.page==='notices')return notices(c);if(state.page==='profile')return profile(c);if(state.page==='residents')return residents(c);if(state.page==='vendors')return vendors(c);if(state.page==='vendorperformance')return await vendorperformance(c);if(state.page==='expenses')return expenses(c);if(state.page==='workorders')return workorders(c)}catch(e){c.innerHTML=`<div class="error">${esc(e.message)}</div>`}}
async function dashboard(c){const d=await api('/dashboard');if(state.role==='resident'){const due=d.due||0; c.innerHTML=`<section class="hero"><div><div class="eyebrow">${i18n.t('myHome')}</div><h2>${esc(state.user.apartment||i18n.t('apartmentNotAssigned'))}</h2><p>${i18n.t('residentAccountTagline')}</p></div><div class="hero-amount"><small>${i18n.t('currentMaintenanceDue')}</small><b>₹${due.toLocaleString('en-IN')}</b></div></section><div class="cards"><div class="stat"><small>${i18n.t('maintenanceDue')}</small><b>₹${due.toLocaleString('en-IN')}</b><em>${due?i18n.t('actionRequired'):i18n.t('allClear')}</em></div><div class="stat"><small>${i18n.t('totalPaid')}</small><b>₹${(d.paid||0).toLocaleString('en-IN')}</b><em>${i18n.t('verifiedPayments')}</em></div><div class="stat"><small>${i18n.t('openRequests').toUpperCase()}</small><b>${d.active_requests||0}</b><em>${i18n.t('inThePipeline')}</em></div><div class="stat"><small>${i18n.t('complaints').toUpperCase()}</small><b>${d.complaints}</b><em>${i18n.t('raisedByYou')}</em></div></div><div class="layout"><div class="panel"><div class="panel-head"><h3>${i18n.t('maintenanceRequests')}</h3><button class="secondary" onclick="go('workorders')">${i18n.t('viewAll')}</button></div>${(d.work_orders||[]).length?d.work_orders.map(residentOrderCard).join(''):`<div class="empty">${i18n.t('noMaintenanceRequestsYet')}</div>`}</div><div class="panel"><div class="panel-head"><h3>${i18n.t('quickActions')}</h3></div><button class="primary" onclick="go('payments')">${i18n.t('payMaintenance')} →</button><br><br><button class="secondary" onclick="go('workorders')">${i18n.t('requestMaintenance')}</button><br><br><button class="secondary" onclick="go('complaints')">${i18n.t('raiseComplaint')}</button></div></div>`}else if(state.role==='vendor'){c.innerHTML=`<section class="hero"><div><div class="eyebrow">${i18n.t('vendorHub')}</div><h2>${i18n.t('vendorHubTitle')}</h2><p>${i18n.t('vendorHubSubtitle')}</p></div><div class="hero-amount"><small>${i18n.t('openJobsAvailable')}</small><b>${d.open_jobs_count||0}</b></div></section><div class="cards"><div class="stat"><small>${i18n.t('activeJobs').toUpperCase()}</small><b>${d.work_orders.length}</b><em>${i18n.t('acceptedInProgress')}</em></div><div class="stat"><small>${i18n.t('openOnBoard')}</small><b>${d.open_jobs_count||0}</b><em>${i18n.t('awaitingVendor')}</em></div></div><div class="layout"><div class="panel"><div class="panel-head"><h3>${i18n.t('myActiveJobs')}</h3><button class="secondary" onclick="go('workorders')">${i18n.t('openBoard')}</button></div>${d.work_orders.length?d.work_orders.map(w=>orderCard(w)).join(''):`<div class="empty">${i18n.t('noActiveJobs')}</div>`}</div><div class="panel"><div class="panel-head"><h3>${i18n.t('newOnBoard')}</h3></div>${(d.open_jobs||[]).length?d.open_jobs.map(w=>orderCard(w)).join(''):`<div class="empty">${i18n.t('nothingOpenNow')}</div>`}</div></div>`}else{c.innerHTML=`<section class="hero"><div><div class="eyebrow">${i18n.t('operations')}</div><h2>${i18n.t('controlRoomTitle')}</h2><p>${i18n.t('controlRoomSubtitle')}</p></div><div class="hero-amount"><small>${i18n.t('collection')}</small><b>₹${(d.collection||0).toLocaleString('en-IN')}</b></div></section>${financeBlock(d.financials)}<div class="cards"><div class="stat"><small>${i18n.t('residents').toUpperCase()}</small><b>${d.residents}</b><em>${i18n.t('registeredLabel')}</em></div><div class="stat"><small>${i18n.t('vendors').toUpperCase()}</small><b>${d.vendors}</b><em>${i18n.t('registeredLabel')}</em></div><div class="stat"><small>${i18n.t('openComplaintsLabel')}</small><b>${d.open_complaints}</b><em>${i18n.t('needsAttention')}</em></div><div class="stat"><small>${i18n.t('openWorkOrdersLabel')}</small><b>${d.open_work_orders||0}</b><em>${i18n.t('awaitingVendor')}</em></div></div><div class="layout"><div class="panel"><div class="panel-head"><h3>${i18n.t('adminShortcuts')}</h3></div><div class="admin-grid"><button class="secondary" onclick="go('residents')">${i18n.t('residents')}</button><button class="secondary" onclick="go('vendors')">${i18n.t('vendors')}</button><button class="secondary" onclick="go('workorders')">${i18n.t('workorders')}</button><button class="secondary" onclick="go('expenses')">${i18n.t('expenses')}</button><button class="secondary" onclick="go('notices')">${i18n.t('notices')}</button><button class="secondary" onclick="go('vendorperformance')">${i18n.t('vendorPerformance')}</button></div></div><div class="panel"><h3>${i18n.t('systemStatus')}</h3><p class="muted">${i18n.t('databaseConnected')} · ${i18n.t('jwtProtected')} · ${i18n.t('paymentGatewayReady')}</p></div></div>`}}
function financeBlock(f){if(!f)return'';return `<div class="page-title" style="margin-bottom:8px"><h2>${i18n.t('financialOverview')}</h2></div><div class="finance-grid"><div class="finance-stat"><small>${i18n.t('totalBilled').toUpperCase()}</small><b>₹${f.total_billed.toLocaleString('en-IN')}</b></div><div class="finance-stat"><small>${i18n.t('collected').toUpperCase()}</small><b>₹${f.total_collected.toLocaleString('en-IN')}</b></div><div class="finance-stat"><small>${i18n.t('pending').toUpperCase()}</small><b>₹${f.total_pending.toLocaleString('en-IN')}</b></div><div class="finance-stat"><small>${i18n.t('expenses').toUpperCase()}</small><b>₹${f.total_expenses.toLocaleString('en-IN')}</b></div><div class="finance-stat"><small>${i18n.t('balance').toUpperCase()}</small><b>₹${f.balance.toLocaleString('en-IN')}</b></div><div class="finance-stat"><small>${i18n.t('collectionRate').toUpperCase()}</small><b>${f.collection_rate}%</b><div class="progress-track"><div class="progress-fill" style="width:${Math.min(f.collection_rate,100)}%"></div></div></div></div>`}
async function vendorperformance(c){const d=await api('/admin/vendor-performance');c.innerHTML=`<div class="page-title"><h2>${i18n.t('vendorPerformance')}</h2><p>${i18n.t('vendorPerfSubtitle')}</p></div>${d.vendor_performance.length?d.vendor_performance.map(v=>`<div class="perf-card"><div class="perf-head"><b>${esc(v.vendor.name)}</b><span class="perf-score">${v.score}/100</span></div><div class="perf-metrics"><div><small>${i18n.t('completed')}</small><b>${v.completed_jobs}</b></div><div><small>${i18n.t('cancelledLabel')}</small><b>${v.cancelled_jobs}</b></div><div><small>${i18n.t('completionRate')}</small><b>${v.completion_rate}%</b></div><div><small>${i18n.t('activeJobs')}</small><b>${v.active_jobs}</b></div><div><small>${i18n.t('avgRatingLabel')}</small><b>${v.vendor.average_rating!=null?'★ '+v.vendor.average_rating:'—'}</b></div></div>${v.average_completion_hours!=null?`<p class="muted" style="margin-top:8px;font-size:12px">${i18n.t('avgCompletionTime')}: ${v.average_completion_hours}h</p>`:''}</div>`).join(''):`<div class="panel empty">${i18n.t('noVendorsYet')}</div>`}`}
function statusLabel(s){if(!s)return'';const key='status'+String(s).split('_').map(w=>w?w[0].toUpperCase()+w.slice(1):'').join('');return i18n.t(key)!==key?i18n.t(key):s.replace('_',' ')}
function go(p){state.page=p;renderShell()}
function orderCard(w){return `<div class="list-card"><div class="list-row"><div><h4>${esc(w.title)}</h4><p>${esc(w.category||i18n.t('generalCategory'))} · ${esc(w.vendor_name)} · ${i18n.t('dueLabel')} ${esc(w.due_date||'—')}</p></div><div style="text-align:right"><span class="badge ${esc(w.status)}">${statusLabel(w.status)}</span>${w.amount?`<div class="amount" style="margin-top:6px">₹${Number(w.amount).toLocaleString('en-IN')}</div>`:''}</div></div></div>`}

function residentOrderCard(w){const assigned=w.vendor_id?`<div class="notice" style="margin:10px 0 0;padding:11px 14px;background:#f4f7f4"><span class="tag">${w.status==='completed'?i18n.t('completedByLabel'):i18n.t('pickedUpBy')}</span><h3 style="font-size:14px;margin:4px 0 2px">${esc(w.vendor_name)}${w.vendor_service?' · '+esc(w.vendor_service):''}</h3><p>${w.vendor_contact?'📞 '+esc(w.vendor_contact):i18n.t('noContactOnFile')}${w.completed_at?' · '+i18n.t('completedAtLabel')+' '+new Date(w.completed_at).toLocaleString('en-IN'):w.accepted_at?' · '+i18n.t('acceptedAtLabel')+' '+new Date(w.accepted_at).toLocaleString('en-IN'):''}</p></div>`:'';const ratingBlock=w.status==='completed'&&w.vendor_id?(w.rating?`<div class="notice" style="margin:10px 0 0;padding:11px 14px;background:#fff8e6"><span class="tag">${i18n.t('yourRatingLabel')}</span><h3 style="font-size:16px;margin:4px 0 2px;letter-spacing:2px;color:#b37a16">${'★'.repeat(w.rating.stars)}${'☆'.repeat(5-w.rating.stars)}</h3>${w.rating.remarks?`<p>${esc(w.rating.remarks)}</p>`:''}</div>`:`<div class="btn-row"><button class="secondary" onclick="rateVendorModal(${w.id})">${i18n.t('rateVendorBtn')}</button></div>`):'';const quotesBtn=w.status==='open'&&w.quotes_count?`<div class="btn-row"><button class="secondary" onclick="quotesModal(${w.id})">${i18n.t('viewQuotesBtn')} (${w.quotes_count})</button></div>`:'';return `<div class="list-card"><div class="list-row"><div><h4>${esc(w.title)}</h4><p>${esc(w.category||i18n.t('generalCategory'))} ${w.due_date?'· '+i18n.t('neededBy')+' '+esc(w.due_date):''}</p>${w.description?`<p>${esc(w.description)}</p>`:''}</div><div style="text-align:right"><span class="badge ${esc(w.status)}">${statusLabel(w.status)}</span>${w.amount?`<div class="amount" style="margin-top:6px">₹${Number(w.amount).toLocaleString('en-IN')}</div>`:''}</div></div>${assigned}${ratingBlock}${quotesBtn}${w.status==='open'?`<div class="btn-row"><button class="cancel" onclick="cancelWorkOrder(${w.id})">${i18n.t('cancelRequest')}</button></div>`:''}${w.vendor_id&&w.amount&&['accepted','in_progress','completed'].includes(w.status)?(w.payment_status==='paid'?`<div class="btn-row"><span class="badge paid">${i18n.t('vendorPaymentPaid')}</span></div>`:`<div class="btn-row"><button class="pay" onclick="payVendor(${w.id})">${i18n.t('payVendorBtn')} ₹${Number(w.amount).toLocaleString('en-IN')} →</button></div>`):''}</div>`}

function vendorOpenCard(w){const mq=w.my_quote;const quoteBlock=mq?`<div class="notice" style="margin:10px 0 0;padding:10px 14px;background:#eef0ff"><span class="tag">${i18n.t('yourQuoteLabel')}</span><h3 style="font-size:15px;margin:4px 0 2px">₹${Number(mq.amount).toLocaleString('en-IN')}</h3>${mq.note?`<p>${esc(mq.note)}</p>`:''}</div>`:'';const quoteBtn=mq?`<button class="secondary" onclick="quoteModal(${w.id})">${i18n.t('updateQuote')}</button><button class="cancel" onclick="withdrawQuote(${w.id},${mq.id})">${i18n.t('withdrawQuote')}</button>`:`<button class="secondary" onclick="quoteModal(${w.id})">${i18n.t('submitQuote')}</button>`;return `<div class="list-card"><div class="list-row"><div><h4>${esc(w.title)}</h4><p>${esc(w.category||i18n.t('generalCategory'))} · ${esc(w.apartment||i18n.t('apartmentNA'))} ${w.due_date?'· '+i18n.t('neededBy')+' '+esc(w.due_date):''}</p>${w.description?`<p>${esc(w.description)}</p>`:''}</div><div style="text-align:right">${w.amount?`<div class="amount">₹${Number(w.amount).toLocaleString('en-IN')}</div>`:''}</div></div>${quoteBlock}<div class="btn-row"><button class="accept" onclick="acceptWorkOrder(${w.id})">${i18n.t('acceptJob')} →</button>${quoteBtn}</div></div>`}

function vendorMineCard(w){return `<div class="list-card"><div class="list-row"><div><h4>${esc(w.title)}</h4><p>${esc(w.category||i18n.t('generalCategory'))} · ${esc(w.apartment||'')} ${w.due_date?'· '+i18n.t('neededBy')+' '+esc(w.due_date):''}</p>${w.description?`<p>${esc(w.description)}</p>`:''}</div><div style="text-align:right"><span class="badge ${esc(w.status)}">${statusLabel(w.status)}</span>${w.amount?`<div class="amount" style="margin-top:6px">₹${Number(w.amount).toLocaleString('en-IN')}</div>`:''}</div></div>${w.status==='accepted'?`<div class="btn-row"><button class="start" onclick="setWorkOrderStatus(${w.id},'in_progress')">${i18n.t('start')}</button><button class="cancel" onclick="withdrawWorkOrder(${w.id})">${i18n.t('withdraw')}</button></div>`:''}${w.status==='in_progress'?`<div class="btn-row"><button class="finish" onclick="setWorkOrderStatus(${w.id},'completed')">${i18n.t('markComplete')} →</button><button class="cancel" onclick="withdrawWorkOrder(${w.id})">${i18n.t('withdraw')}</button></div>`:''}</div>`}

function adminOrderCard(w){const ratingLine=w.rating?`<p class="muted" style="font-size:11px;margin-top:6px">${i18n.t('ratingLabel')}: ${'★'.repeat(w.rating.stars)}${'☆'.repeat(5-w.rating.stars)}</p>`:'';const quotesBtn=w.status==='open'?`<div class="btn-row"><button class="secondary" onclick="quotesModal(${w.id})">${i18n.t('viewQuotesBtn')}${w.quotes_count?` (${w.quotes_count})`:''}</button></div>`:'';return `<div class="list-card"><div class="list-row"><div><h4>${esc(w.title)}</h4><p>${esc(w.category||i18n.t('generalCategory'))} · ${esc(w.resident_name||i18n.t('postedByAdmin'))}${w.apartment?' ('+esc(w.apartment)+')':''} → ${esc(w.vendor_name)}</p>${w.description?`<p>${esc(w.description)}</p>`:''}</div><div style="text-align:right"><span class="badge ${esc(w.status)}">${statusLabel(w.status)}</span>${w.amount?`<div class="amount" style="margin-top:6px">₹${Number(w.amount).toLocaleString('en-IN')}</div>`:''}</div></div>${ratingLine}${quotesBtn}</div>`}

async function acceptWorkOrder(id){try{await api('/work-orders/'+id+'/accept',{method:'PATCH'});toast(i18n.t('jobAccepted')+' 🎉');loadPage()}catch(e){toast(e.message)}}
async function setWorkOrderStatus(id,status){try{await api('/work-orders/'+id+'/status',{method:'PATCH',body:JSON.stringify({status})});toast(status==='completed'?i18n.t('jobMarkedComplete')+' 🎉':i18n.t('statusUpdated'));loadPage()}catch(e){toast(e.message)}}
async function cancelWorkOrder(id){if(!confirm(i18n.t('confirmCancelRequest')))return;setWorkOrderStatus(id,'cancelled')}
async function withdrawWorkOrder(id){if(!confirm(i18n.t('confirmWithdraw')))return;try{await api(`/work-orders/${id}/withdraw`,{method:'PATCH'});toast(i18n.t('withdrewFromJob'));loadPage()}catch(e){toast(e.message)}}

function quoteModal(wid){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button class="close" onclick="$('#modal').remove()">×</button><h3>${i18n.t('submitQuoteModalTitle')}</h3><form id="qf"><div class="field"><label>${i18n.t('quoteAmountLabel')}</label><input id="qamt" type="number" min="1" step="1" required placeholder="₹"></div><div class="field"><label>${i18n.t('quoteNoteLabel')}</label><textarea id="qnote" rows="3" placeholder="${i18n.t('quoteNotePlaceholder')}"></textarea></div><button class="primary">${i18n.t('submitQuoteBtn')}</button></form></div></div>`);$('#qf').onsubmit=async e=>{e.preventDefault();try{await api(`/work-orders/${wid}/quotes`,{method:'POST',body:JSON.stringify({amount:$('#qamt').value,note:$('#qnote').value})});$('#modal').remove();toast(i18n.t('quoteSubmitted'));loadPage()}catch(x){toast(x.message)}}}

async function quotesModal(wid){let quotes=[];try{const d=await api(`/work-orders/${wid}/quotes`);quotes=d.quotes}catch(e){toast(e.message);return}document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button class="close" onclick="$('#modal').remove()">×</button><h3>${i18n.t('quotesReceivedTitle')}</h3>${quotes.length?quotes.map(q=>`<div class="list-card"><div class="list-row"><div><h4>${esc(q.vendor_name)}</h4><p>${esc(q.vendor_service||'')}${q.vendor_contact?' · 📞 '+esc(q.vendor_contact):''}</p>${q.note?`<p>${esc(q.note)}</p>`:''}</div><div style="text-align:right"><div class="amount">₹${Number(q.amount).toLocaleString('en-IN')}</div><span class="badge ${esc(q.status)}">${statusLabel(q.status)}</span></div></div>${q.status==='pending'?`<div class="btn-row"><button class="accept" onclick="acceptQuote(${wid},${q.id})">${i18n.t('acceptQuoteBtn')}</button><button class="cancel" onclick="rejectQuote(${wid},${q.id})">${i18n.t('declineQuoteBtn')}</button></div>`:''}</div>`).join(''):`<div class="empty">${i18n.t('noQuotesYet')}</div>`}</div></div>`)}

async function acceptQuote(wid,qid){if(!confirm(i18n.t('confirmAcceptQuote')))return;try{await api(`/work-orders/${wid}/quotes/${qid}/accept`,{method:'PATCH'});const m=$('#modal');if(m)m.remove();toast(i18n.t('quoteAccepted'));loadPage()}catch(e){toast(e.message)}}

async function rejectQuote(wid,qid){try{await api(`/work-orders/${wid}/quotes/${qid}/reject`,{method:'PATCH'});toast(i18n.t('quoteDeclined'));const m=$('#modal');if(m)m.remove();quotesModal(wid)}catch(e){toast(e.message)}}

async function withdrawQuote(wid,qid){if(!confirm(i18n.t('confirmWithdrawQuote')))return;try{await api(`/work-orders/${wid}/quotes/${qid}/withdraw`,{method:'PATCH'});toast(i18n.t('quoteWithdrawn'));loadPage()}catch(e){toast(e.message)}}

function rateVendorModal(wid){let selected=0;function starsHtml(){return [1,2,3,4,5].map(n=>`<span class="star-pick" data-n="${n}" style="color:${n<=selected?'#b37a16':'#dde3df'}">★</span>`).join('')}function renderStars(){const row=$('#starRow');row.innerHTML=starsHtml();row.querySelectorAll('.star-pick').forEach(s=>s.onclick=()=>{selected=Number(s.dataset.n);renderStars()})}document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button class="close" onclick="$('#modal').remove()">×</button><h3>${i18n.t('rateVendorModalTitle')}</h3><div id="starRow" class="star-row"></div><form id="rf2"><div class="field"><label>${i18n.t('remarksOptional')}</label><textarea id="rremarks" rows="3"></textarea></div><button class="primary">${i18n.t('submitRatingBtn')}</button></form></div></div>`);renderStars();$('#rf2').onsubmit=async e=>{e.preventDefault();if(!selected){toast(i18n.t('pickStarRating'));return}try{await api(`/work-orders/${wid}/rating`,{method:'POST',body:JSON.stringify({stars:selected,remarks:$('#rremarks').value})});$('#modal').remove();toast(i18n.t('ratingSubmitted'));loadPage()}catch(x){toast(x.message)}}}

function quoteHistoryCard(q){return `<div class="list-card"><div class="list-row"><div><h4>${esc(q.work_order_title||'—')}</h4><p>${esc(q.work_order_category||'')}${q.work_order_apartment?' · '+esc(q.work_order_apartment):''}</p>${q.note?`<p>${esc(q.note)}</p>`:''}</div><div style="text-align:right"><div class="amount">₹${Number(q.amount).toLocaleString('en-IN')}</div><span class="badge ${esc(q.status)}">${statusLabel(q.status)}</span></div></div>${q.status==='pending'?`<div class="btn-row"><button class="cancel" onclick="withdrawQuote(${q.work_order_id},${q.id})">${i18n.t('withdrawQuote')}</button></div>`:''}</div>`}

async function downloadReceipt(id, clickEvent){
  const button=clickEvent&&clickEvent.currentTarget?clickEvent.currentTarget:null;
  const original=button?button.textContent:'';
  try{
    if(button){button.disabled=true;button.textContent='Preparing PDF…'}
    const r=await fetch(`${API}/payments/${id}/receipt-link`,{
      method:'POST',
      headers:state.token?{Authorization:`Bearer ${state.token}`}: {},
      cache:'no-store'
    });
    const d=await r.json().catch(()=>({}));
    if(!r.ok || !d.url) throw new Error(d.error||i18n.t('receiptDownloadFailed'));

    // Let the browser perform a normal navigation to an endpoint that returns
    // Content-Disposition: attachment. No blob, object URL, or popup is used.
    const link=document.createElement('a');
    link.href=new URL(d.url,window.location.origin).href;
    link.target='_blank';
    link.rel='noopener';
    link.style.display='none';
    document.body.appendChild(link);
    link.click();
    setTimeout(()=>link.remove(),1000);
  }catch(e){
    toast(e.message||i18n.t('receiptDownloadFailed'));
  }finally{
    if(button){button.disabled=false;button.textContent=original||i18n.t('downloadReceipt')}
  }
}

async function workOrderModal(isAdmin){let vendorOptions='',residentOptions='';if(isAdmin){try{const vd=await api('/admin/vendors');vendorOptions=vd.vendors.map(v=>`<option value="${v.id}">${esc(v.name)} (${esc(v.service)})</option>`).join('')}catch{}try{const ud=await api('/admin/users');residentOptions=ud.users.filter(u=>u.role==='resident').map(u=>`<option value="${u.id}">${esc(u.name)} — ${esc(u.apartment||'no unit')}</option>`).join('')}catch{}}const cats=[['Plumbing','catPlumbing'],['Electrical','catElectrical'],['Carpentry','catCarpentry'],['Cleaning','catCleaning'],['Painting','catPainting']];document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button class="close" onclick="$('#modal').remove()">×</button><h3>${isAdmin?i18n.t('postWorkOrderModalTitle'):i18n.t('newMaintenanceRequestModalTitle')}</h3><form id="wf"><div class="field"><label>${i18n.t('categoryLabel')}</label><select id="wcat">${cats.map(([v,k])=>`<option value="${v}">${i18n.t(k)}</option>`).join('')}</select></div><div class="field"><label>${i18n.t('titleLabel')}</label><input id="wtitle" required placeholder="e.g. Fix leaking kitchen tap"></div><div class="field"><label>${i18n.t('descriptionLabel')}</label><textarea id="wdesc" rows="3" placeholder="${i18n.t('vendorDetailsPlaceholder')}"></textarea></div><div class="grid2"><div class="field"><label>${i18n.t('budgetOptional')}</label><input id="wamt" type="number" min="0" step="1" placeholder="₹"></div><div class="field"><label>${i18n.t('neededBy')}</label><input id="wdue" placeholder="e.g. 10 Sep 2026"></div></div>${isAdmin?`<div class="field"><label>${i18n.t('residentOptional')}</label><select id="wres"><option value="">${i18n.t('noneOption')}</option>${residentOptions}</select></div><div class="field"><label>${i18n.t('assignVendorOptional')}</label><select id="wven"><option value="">${i18n.t('leaveOpenOption')}</option>${vendorOptions}</select></div>`:''}<button class="primary">${isAdmin?i18n.t('postWorkOrderSubmit'):i18n.t('submitRequest')}</button></form></div></div>`);$('#wf').onsubmit=async e=>{e.preventDefault();try{const body={category:$('#wcat').value,title:$('#wtitle').value,description:$('#wdesc').value,amount:$('#wamt').value||0,due_date:$('#wdue').value};if(isAdmin){const rv=$('#wres').value,vv=$('#wven').value;if(rv)body.resident_id=Number(rv);if(vv)body.vendor_id=Number(vv)}await api('/work-orders',{method:'POST',body:JSON.stringify(body)});$('#modal').remove();toast(isAdmin?i18n.t('workOrderPosted'):i18n.t('requestSubmitted'));loadPage()}catch(x){toast(x.message)}}}
async function payments(c){
    if(state.role==='admin'){
        const [p,b]=await Promise.all([api('/admin/payments'),api('/admin/maintenance-bills')]);
        c.innerHTML=`<div class="page-title"><h2>${i18n.t('payments')}</h2><p>${i18n.t('adminPaymentsSubtitle')}</p></div>
        <div class="panel" style="margin-bottom:18px"><div class="panel-head"><div><h3>${i18n.t('maintenanceBilling')}</h3><p class="muted">${i18n.t('maintenanceBillingSubtitle')}</p></div><button class="primary" style="width:auto" onclick="maintenanceBillModal()">${i18n.t('assignMaintenance')}</button></div>
        ${b.bills.length?`<table class="table"><thead><tr><th>${i18n.t('tableUser')}</th><th>${i18n.t('tableApartment')}</th><th>${i18n.t('billingMonth')}</th><th>${i18n.t('tableAmount')}</th><th>${i18n.t('dueDate')}</th><th>${i18n.t('tableStatus')}</th></tr></thead><tbody>${b.bills.map(x=>`<tr><td>${esc(x.resident_name||x.user_id)}</td><td>${esc(x.apartment||'—')}</td><td>${esc(x.month)}</td><td>₹${Number(x.amount).toLocaleString('en-IN')}</td><td>${esc(x.due_date)}</td><td><span class="badge ${esc(x.status)}">${statusLabel(x.status)}</span></td></tr>`).join('')}</tbody></table>`:`<div class="empty">${i18n.t('noMaintenanceBills')}</div>`}</div>
        <div class="panel"><div class="panel-head"><h3>${i18n.t('paymentHistory')}</h3></div>
        ${p.payments.length?`<table class="table"><thead><tr><th>${i18n.t('tableDate')}</th><th>${i18n.t('tableUser')}</th><th>${i18n.t('tableDescription')}</th><th>${i18n.t('tableAmount')}</th><th>${i18n.t('tableStatus')}</th><th>${i18n.t('tableReceipt')}</th></tr></thead>
        <tbody>${p.payments.map(x=>`<tr><td>${new Date(x.created_at).toLocaleDateString('en-IN')}</td><td>${esc(x.user_name||x.user_id)}</td><td>${esc(x.description)}</td><td>₹${Number(x.amount).toLocaleString('en-IN')}</td><td><span class="badge ${esc(x.status)}">${statusLabel(x.status)}</span></td><td>${x.status==='paid'?`<button class="secondary" onclick="downloadReceipt(${x.id}, event)">${i18n.t('downloadReceipt')}</button>`:'—'}</td></tr>`).join('')}</tbody></table>`:`<div class="empty">${i18n.t('noPaymentsYet')}</div>`}</div>`;
        return;
    }

    const [d,p]=await Promise.all([api('/bills'),api('/payments')]);
    c.innerHTML=`<div class="page-title"><h2>${i18n.t('payments')}</h2><p>${i18n.t('residentPaymentsSubtitle')}</p></div>
    ${d.bills.length?d.bills.map(b=>`<div class="list-card"><div class="list-row"><div><h4>${esc(b.description)}</h4><p>${esc(b.month)} · ${i18n.t('dueLabel')} ${esc(b.due_date)}</p></div>
    <div style="text-align:right"><div class="amount">₹${Number(b.amount).toLocaleString('en-IN')}</div>${b.status==='paid'?`<span class="badge paid">${i18n.t('statusPaid')}</span>`:'<button class="pay" onclick="payBill('+b.id+')">'+i18n.t('payNow')+' →</button>'}</div></div></div>`).join(''):`<div class="panel empty">${i18n.t('noMaintenanceBills')}</div>`}
    <div class="panel" style="margin-top:18px"><div class="panel-head"><h3>${i18n.t('paymentHistory')}</h3></div>
    ${p.payments.length?`<table class="table"><thead><tr><th>${i18n.t('tableDate')}</th><th>${i18n.t('tableDescription')}</th><th>${i18n.t('tableAmount')}</th><th>${i18n.t('tableStatus')}</th><th>${i18n.t('tableReceipt')}</th></tr></thead>
    <tbody>${p.payments.map(x=>`<tr><td>${new Date(x.created_at).toLocaleDateString('en-IN')}</td><td>${esc(x.description)}</td><td>₹${Number(x.amount).toLocaleString('en-IN')}</td><td><span class="badge ${esc(x.status)}">${statusLabel(x.status)}</span></td><td>${x.status==='paid'?`<button class="secondary" onclick="downloadReceipt(${x.id}, event)">${i18n.t('downloadReceipt')}</button>`:'—'}</td></tr>`).join('')}</tbody></table>`:`<div class="empty">${i18n.t('noPaymentsYet')}</div>`}</div>`;
}

function maintenanceBillModal(){api('/admin/users').then(d=>{const residents=d.users.filter(u=>u.role==='resident');document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button type="button" class="close" onclick="$('#modal').remove()">×</button><h3>${i18n.t('assignMaintenance')}</h3><div id="billFormError"></div><form id="mbf"><div class="field"><label>${i18n.t('tableUser')}</label><select id="mbres" required>${residents.map(u=>`<option value="${u.id}">${esc(u.name)} — ${esc(u.apartment||'no unit')}</option>`).join('')}</select></div><div class="grid2"><div class="field"><label>${i18n.t('billingMonth')}</label><input id="mbmonth" required placeholder="September 2026"></div><div class="field"><label>${i18n.t('dueDate')}</label><input id="mbdue" required placeholder="05 October 2026"></div></div><div class="field"><label>${i18n.t('tableAmount')}</label><input id="mbamount" type="number" min="1" step="0.01" required placeholder="2500"></div><div class="field"><label>${i18n.t('descriptionLabel')}</label><input id="mbdesc" value="Monthly Maintenance" maxlength="255"></div><button class="primary">${i18n.t('assignMaintenance')}</button></form></div></div>`);$('#mbf').onsubmit=async e=>{e.preventDefault();const error=$('#billFormError');error.innerHTML='';try{await api('/admin/maintenance-bills',{method:'POST',body:JSON.stringify({resident_id:Number($('#mbres').value),month:$('#mbmonth').value,due_date:$('#mbdue').value,amount:Number($('#mbamount').value),description:$('#mbdesc').value})});$('#modal').remove();toast(i18n.t('maintenanceAssigned'));loadPage()}catch(x){error.innerHTML=`<div class="error">${esc(x.message)}</div>`}}}).catch(e=>toast(e.message))}
async function payVendor(id){try{const o=await api('/payments/work-order/create-order',{method:'POST',body:JSON.stringify({work_order_id:id})});if(typeof Razorpay==='undefined')throw new Error(i18n.t('razorpayLoadError'));const r=new Razorpay({key:o.key_id,amount:o.amount,currency:o.currency,name:o.name,description:o.description,order_id:o.order_id,prefill:{name:state.user.name,email:state.user.email},handler:async resp=>{try{await api('/payments/verify',{method:'POST',body:JSON.stringify(resp)});toast(i18n.t('vendorPaymentVerified'));loadPage()}catch(e){toast(e.message)}}});r.open()}catch(e){toast(e.message)}}
async function payBill(id){try{const o=await api('/payments/create-order',{method:'POST',body:JSON.stringify({bill_id:id})});if(typeof Razorpay==='undefined')throw new Error(i18n.t('razorpayLoadError'));const r=new Razorpay({key:o.key_id,amount:o.amount,currency:o.currency,name:o.name,description:o.description,order_id:o.order_id,prefill:{name:state.user.name,email:state.user.email},theme:{color:'#1d6b4b'},handler:async resp=>{try{await api('/payments/verify',{method:'POST',body:JSON.stringify(resp)});toast(i18n.t('paymentVerified'));loadPage()}catch(e){toast(e.message)}}});r.open()}catch(e){toast(e.message)}}
async function receipts(c){const d=await api('/payments');c.innerHTML=`<div class="page-title"><h2>${i18n.t('receipts')}</h2><p>${i18n.t('receiptsSubtitle')}</p></div>${d.payments.filter(p=>p.status==='paid').map(p=>`<div class="list-card"><div class="list-row"><div><h4>${i18n.t('maintenanceReceipt')} #${p.id}</h4><p>${new Date(p.created_at).toLocaleDateString('en-IN')} · ${esc(p.razorpay_payment_id||i18n.t('verifiedLabel'))}</p></div><div style="text-align:right"><div class="amount">₹${p.amount.toLocaleString('en-IN')}</div><button class="secondary" style="margin-top:8px" onclick="downloadReceipt(${p.id}, event)">${i18n.t('downloadReceipt')}</button></div></div></div>`).join('')||`<div class="panel empty">${i18n.t('noReceiptsYet')}</div>`}`}
function complaintTimeline(status){const steps=[['open','timelineSubmitted'],['in_progress','timelineInProgress'],['resolved','timelineResolved'],['closed','timelineClosed']];const idx=steps.findIndex(s=>s[0]===status);return `<div class="timeline">${steps.map((s,i)=>`<div class="timeline-step ${i<idx?'done':''} ${i===idx?'current':''}"><div class="timeline-dot">${i<idx?'✓':i===idx?'●':'○'}</div><div class="timeline-label">${i18n.t(s[1])}</div></div>`).join('')}</div>`}
async function complaints(c){const d=await api('/complaints');c.innerHTML=`<div class="page-title"><h2>${i18n.t('complaints')}</h2><p>${i18n.t('complaintsSubtitle')}</p></div><button class="primary" style="width:auto;margin-bottom:15px" onclick="complaintModal()">${i18n.t('newComplaint')}</button>${d.complaints.map(x=>`<div class="list-card"><div class="list-row"><div><h4>${esc(x.subject)}</h4><p>${esc(x.category)} · ${new Date(x.created_at).toLocaleDateString('en-IN')}</p><p>${esc(x.description)}</p></div><span class="badge ${x.status}">${statusLabel(x.status)}</span></div>${state.role==='resident'?complaintTimeline(x.status):''}${x.updated_at?`<p class="muted" style="font-size:11px;margin-top:6px">${i18n.t('lastUpdated')} ${new Date(x.updated_at).toLocaleString('en-IN')}</p>`:''}</div>`).join('')||`<div class="panel empty">${i18n.t('noComplaintsYet')}</div>`}`}
function complaintModal(){const cats=[['Plumbing','catPlumbing'],['Electrical','catElectrical'],['Security','catSecurity'],['Cleaning','catCleaning'],['Other','catOther']];document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button class="close" onclick="$('#modal').remove()">×</button><h3>${i18n.t('raiseComplaint')}</h3><form id="cf"><div class="field"><label>${i18n.t('categoryLabel')}</label><select id="cc">${cats.map(([v,k])=>`<option value="${v}">${i18n.t(k)}</option>`).join('')}</select></div><div class="field"><label>${i18n.t('subjectLabel')}</label><input id="cs" required></div><div class="field"><label>${i18n.t('descriptionLabel')}</label><textarea id="cd" rows="4" required></textarea></div><button class="primary">${i18n.t('submitComplaint')}</button></form></div></div>`);$('#cf').onsubmit=async e=>{e.preventDefault();try{await api('/complaints',{method:'POST',body:JSON.stringify({category:$('#cc').value,subject:$('#cs').value,description:$('#cd').value})});$('#modal').remove();toast(i18n.t('complaintSubmitted'));loadPage()}catch(x){toast(x.message)}}}
async function notices(c){const d=await api('/notices');const isAdmin=state.role==='admin';c.innerHTML=`<div class="page-title"><h2>${i18n.t('notices')}</h2><p>${i18n.t('noticesSubtitle')}</p></div>${isAdmin?`<button class="primary" style="width:auto;margin-bottom:15px" onclick="noticeModal()">${i18n.t('postNotice')}</button>`:''}${d.notices.length?d.notices.map(n=>`<div class="notice"><span class="tag">${esc(n.tag)} · ${new Date(n.created_at).toLocaleDateString('en-IN',{day:'2-digit',month:'short'}).toUpperCase()}</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p>${isAdmin?`<div class="btn-row"><button class="cancel" onclick="deleteNotice(${n.id})">${i18n.t('deleteBtn')}</button></div>`:''}</div>`).join(''):`<div class="panel empty">${i18n.t('noNoticesYet')}</div>`}`}
function noticeModal(){const tags=[['COMMUNITY','tagCommunity'],['IMPORTANT','tagImportant'],['MAINTENANCE','tagMaintenance'],['EVENT','tagEvent']];document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button class="close" onclick="$('#modal').remove()">×</button><h3>${i18n.t('postNoticeModalTitle')}</h3><form id="nf"><div class="field"><label>${i18n.t('tagLabel')}</label><select id="ntag">${tags.map(([v,k])=>`<option value="${v}">${i18n.t(k)}</option>`).join('')}</select></div><div class="field"><label>${i18n.t('titleLabel')}</label><input id="ntitle" required placeholder="e.g. Water tank cleaning"></div><div class="field"><label>${i18n.t('messageLabel')}</label><textarea id="nbody" rows="4" required></textarea></div><button class="primary">${i18n.t('postNoticeBtn')}</button></form></div></div>`);$('#nf').onsubmit=async e=>{e.preventDefault();try{await api('/notices',{method:'POST',body:JSON.stringify({tag:$('#ntag').value,title:$('#ntitle').value,body:$('#nbody').value})});$('#modal').remove();toast(i18n.t('noticePosted'));loadPage()}catch(x){toast(x.message)}}}
async function deleteNotice(id){if(!confirm(i18n.t('confirmDeleteNotice')))return;try{await api('/notices/'+id,{method:'DELETE'});toast(i18n.t('noticeDeleted'));loadPage()}catch(e){toast(e.message)}}
function profile(c){c.innerHTML=`<div class="page-title"><h2>${i18n.t('myProfile')}</h2><p>${i18n.t('profileSubtitle')}</p></div><div class="profile-box"><div class="big-avatar">${esc(state.user.name[0].toUpperCase())}</div><div><h3 style="margin:0">${esc(state.user.name)}</h3><p class="muted">${esc(state.user.email)} · ${esc(i18n.t(state.user.role))}</p></div></div><div class="form-card"><form id="pf"><div class="grid2"><div class="field"><label>${i18n.t('name')}</label><input id="pn" value="${esc(state.user.name)}" required></div><div class="field"><label>${i18n.t('phone')}</label><input id="pp" value="${esc(state.user.phone||'')}"></div></div><div class="field"><label>${i18n.t('apartment')}</label><input id="pa" value="${esc(state.user.apartment||'')}"></div><button class="primary">${i18n.t('save')}</button></form></div>`;$('#pf').onsubmit=async e=>{e.preventDefault();try{const d=await api('/auth/profile',{method:'PUT',body:JSON.stringify({name:$('#pn').value,phone:$('#pp').value,apartment:$('#pa').value})});state.user=d.user;localStorage.setItem('nestledgerUser',JSON.stringify(d.user));toast(i18n.t('profileUpdated'));renderShell()}catch(x){toast(x.message)}}}
async function residents(c){const d=await api('/admin/users');const users=d.users.filter(u=>u.role==='resident');c.innerHTML=`<div class="page-title"><h2>${i18n.t('residents')}</h2><p>${i18n.t('residentsSubtitle')}</p></div><button class="primary" style="width:auto;margin-bottom:15px" onclick="residentModal()">Add resident</button><div class="panel"><table class="table"><thead><tr><th>${i18n.t('tableName')}</th><th>${i18n.t('tableEmail')}</th><th>${i18n.t('tableApartment')}</th><th>${i18n.t('tablePhone')}</th></tr></thead><tbody>${users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(u.apartment||'—')}</td><td>${esc(u.phone||'—')}</td></tr>`).join('')||`<tr><td colspan="4">No residents yet</td></tr>`}</tbody></table></div>`}
function residentModal(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button type="button" class="close" onclick="$('#modal').remove()">×</button><h3>Add resident</h3><div id="residentFormError"></div><form id="rf" novalidate><div class="field"><label>Name</label><input id="rn" autocomplete="name"></div><div class="field"><label>Email</label><input id="re" type="email" autocomplete="email"></div><div class="grid2"><div class="field"><label>Phone</label><input id="rp" inputmode="numeric" placeholder="9876543210" autocomplete="tel"></div><div class="field"><label>Apartment / Flat</label><input id="ra" placeholder="A-204"></div></div><button id="residentSubmit" type="submit" class="primary">Create resident</button></form></div></div>`);$('#rf').onsubmit=async e=>{e.preventDefault();const name=$('#rn').value.trim(),email=$('#re').value.trim(),phone=$('#rp').value.trim(),apartment=$('#ra').value.trim(),error=$('#residentFormError'),button=$('#residentSubmit');error.innerHTML='';if(!name||!email||!phone||!apartment){error.innerHTML='<div class="error">Please fill in Name, Email, Phone and Apartment / Flat.</div>';return}if(!validEmail(email)){error.innerHTML='<div class="error">Enter a valid email address.</div>';return}if(!validPhone(phone)){error.innerHTML='<div class="error">Enter a valid 10-digit Indian phone number.</div>';return}button.disabled=true;button.textContent='Creating...';try{const d=await api('/admin/residents',{method:'POST',body:JSON.stringify({name,email,phone,apartment})});$('#modal').remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="tempPasswordModal"><div class="modal"><button type="button" class="close" onclick="$('#tempPasswordModal').remove();loadPage()">×</button><h3>Resident created</h3><p>Give this temporary password to the resident. It is shown only once.</p><div class="panel"><b>${esc(d.temporary_password)}</b></div><button type="button" class="primary" onclick="$('#tempPasswordModal').remove();loadPage()">Done</button></div></div>`)}catch(x){error.innerHTML=`<div class="error">${esc(x.message)}</div>`;toast(x.message);button.disabled=false;button.textContent='Create resident'}}}
async function vendors(c){const d=await api('/admin/vendors');c.innerHTML=`<div class="page-title"><h2>${i18n.t('vendors')}</h2><p>${i18n.t('vendorsSubtitle')}</p></div><button class="primary" style="width:auto;margin-bottom:15px" onclick="vendorModal()">${i18n.t('addVendor')}</button><div class="panel"><table class="table"><thead><tr><th>${i18n.t('tableName')}</th><th>Job title</th><th>${i18n.t('tableContact')}</th><th>${i18n.t('tableStatus')}</th><th>${i18n.t('tableRating')}</th></tr></thead><tbody>${d.vendors.map(v=>`<tr><td>${esc(v.name)}</td><td>${esc(v.service)}</td><td>${esc(v.contact)}</td><td><span class="badge ${v.status}">${statusLabel(v.status)}</span></td><td>${v.average_rating!=null?'★ '+v.average_rating+' ('+v.rating_count+')':i18n.t('noRatingsYet')}</td></tr>`).join('')||`<tr><td colspan="5">No vendors yet</td></tr>`}</tbody></table></div>`}
function vendorModal(){const jobs=['Plumber','Electrician','Carpenter','Painter','Cleaner'];document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button type="button" class="close" onclick="$('#modal').remove()">×</button><h3>${i18n.t('addVendorModalTitle')}</h3><div id="vendorFormError"></div><form id="vf" novalidate><div class="field"><label>${i18n.t('name')}</label><input id="vn" autocomplete="name"></div><div class="field"><label>Email</label><input id="ve" type="email" autocomplete="email"></div><div class="field"><label>Password</label><input id="vp" type="password" minlength="8" autocomplete="new-password"></div><div class="field"><label>Job title</label><select id="vs">${jobs.map(j=>`<option value="${j}">${j}</option>`).join('')}</select></div><div class="field"><label>${i18n.t('contactLabel')}</label><input id="vc" inputmode="numeric" placeholder="9876543210" autocomplete="tel"></div><button id="vendorSubmit" type="submit" class="primary">${i18n.t('saveVendor')}</button></form></div></div>`);$('#vf').onsubmit=async e=>{e.preventDefault();const name=$('#vn').value.trim(),email=$('#ve').value.trim(),password=$('#vp').value,job_title=$('#vs').value,contact=$('#vc').value.trim(),error=$('#vendorFormError'),button=$('#vendorSubmit');error.innerHTML='';if(!name||!email||!password||!contact){error.innerHTML='<div class="error">Please fill in Name, Email, Password and Contact.</div>';return}if(!validEmail(email)){error.innerHTML='<div class="error">Enter a valid email address.</div>';return}if(password.length<8){error.innerHTML='<div class="error">Password must be at least 8 characters.</div>';return}if(!validPhone(contact)){error.innerHTML='<div class="error">Enter a valid 10-digit Indian phone number.</div>';return}button.disabled=true;button.textContent='Creating...';try{await api('/admin/vendors',{method:'POST',body:JSON.stringify({name,email,password,job_title,contact})});$('#modal').remove();toast('Vendor account created successfully');loadPage()}catch(x){error.innerHTML=`<div class="error">${esc(x.message)}</div>`;toast(x.message);button.disabled=false;button.textContent=i18n.t('saveVendor')}}}
async function expenses(c){const d=await api('/admin/expenses');c.innerHTML=`<div class="page-title"><h2>${i18n.t('expenses')}</h2><p>${i18n.t('expensesSubtitle')}</p></div><button class="primary" style="width:auto;margin-bottom:15px" onclick="expenseModal()">${i18n.t('addExpense')}</button><div class="panel"><table class="table"><thead><tr><th>${i18n.t('tableCategory')}</th><th>${i18n.t('tableDescription')}</th><th>${i18n.t('tableAmount')}</th><th>${i18n.t('tableDate')}</th></tr></thead><tbody>${d.expenses.map(e=>`<tr><td>${esc(e.category)}</td><td>${esc(e.description)}</td><td>₹${e.amount.toLocaleString('en-IN')}</td><td>${new Date(e.created_at).toLocaleDateString('en-IN')}</td></tr>`).join('')||`<tr><td colspan="4">${i18n.t('noExpensesRow')}</td></tr>`}</tbody></table></div>`}
function expenseModal(){document.body.insertAdjacentHTML('beforeend',`<div class="modal-backdrop" id="modal"><div class="modal"><button class="close" onclick="$('#modal').remove()">×</button><h3>${i18n.t('addExpenseModalTitle')}</h3><form id="ef"><div class="field"><label>${i18n.t('categoryLabel')}</label><input id="ec" required></div><div class="field"><label>${i18n.t('descriptionLabel')}</label><input id="ed" required></div><div class="field"><label>${i18n.t('amountLabel')}</label><input id="ea" type="number" min="0" step="0.01" required></div><button class="primary">${i18n.t('saveExpense')}</button></form></div></div>`);$('#ef').onsubmit=async e=>{e.preventDefault();try{await api('/admin/expenses',{method:'POST',body:JSON.stringify({category:$('#ec').value,description:$('#ed').value,amount:Number($('#ea').value)})});$('#modal').remove();toast(i18n.t('expenseAdded'));loadPage()}catch(x){toast(x.message)}}}
async function workorders(c){const d=await api('/work-orders');const list=d.work_orders;if(state.role==='resident'){c.innerHTML=`<div class="page-title"><h2>${i18n.t('maintenanceRequests')}</h2><p>${i18n.t('maintenanceRequestsSubtitle')}</p></div><button class="primary" style="width:auto;margin-bottom:15px" onclick="workOrderModal()">${i18n.t('newRequest')}</button>${list.length?list.map(residentOrderCard).join(''):`<div class="panel empty">${i18n.t('noRequestsYet')}</div>`}`}else if(state.role==='vendor'){const buckets=[['open',i18n.t('openRequests'),vendorOpenCard],['accepted',i18n.t('waitingToStart'),vendorMineCard],['in_progress',i18n.t('inProgress'),vendorMineCard],['completed',i18n.t('completed'),vendorMineCard],['cancelled',i18n.t('cancelledWithdrawn'),vendorMineCard]];c.innerHTML=`<div class="page-title"><h2>${i18n.t('jobBoardTitle')}</h2><p>${i18n.t('jobBoardSubtitle')}</p></div>${buckets.map(([status,label,cardFn])=>{const items=list.filter(w=>w.status===status);return `<div class="section-label">${label} · ${items.length}</div>${items.length?items.map(cardFn).join(''):`<div class="panel empty">${i18n.t('noData')}</div>`}`}).join('')}<div class="section-label">${i18n.t('myQuotationsTitle')}</div><div id="myQuotesBox"><div class="panel empty">${i18n.t('loading')}</div></div>`;try{const qd=await api('/vendors/me/quotes');const box=$('#myQuotesBox');if(box)box.innerHTML=qd.quotes.length?qd.quotes.map(quoteHistoryCard).join(''):`<div class="panel empty">${i18n.t('noQuotesSubmittedYet')}</div>`}catch(e){const box=$('#myQuotesBox');if(box)box.innerHTML=`<div class="error">${esc(e.message)}</div>`}}else{c.innerHTML=`<div class="page-title"><h2>${i18n.t('workorders')}</h2><p>${i18n.t('workOrdersSubtitle')}</p></div><button class="primary" style="width:auto;margin-bottom:15px" onclick="workOrderModal(true)">${i18n.t('postWorkOrder')}</button>${list.length?list.map(adminOrderCard).join(''):`<div class="panel empty">${i18n.t('noWorkOrdersYet')}</div>`}`}}
render();
setInterval(()=>{if(state.token&&document.visibilityState==='visible')loadPage()},15000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.token)loadPage()});
